Function MergeAVLTrees(T1, T2)
{
    // Step 1: Find min and max of T2
    min2 = FindMin(T2)  // Follow left links
    max2 = FindMax(T2)  // Follow right links

    // Step 2: Search for attachment point in T1
    v = Root1
    while( v != null):
        x = v.value
        if( max2 < x and v.left == null)
        {    v.left = Root2
            return Root1  // Merge successful
        }
        else if (min2 > x and v.right == null)
        {    v.right = Root2
            return Root1  // Merge successful
        }
        else if (min2 <= x <= max2)
        {    return "Cannot merge"  // T2's values conflict
        }
        else if( max2 < x)
            v = v.left
        else if( min2 > x)
            v = v.right

    return "Cannot merge"  // No attachment point found
}

